## 8. Recommended Fix

```cpp
CameraMetaDataFromMem::CameraMetaDataFromMem(const char* document)
{
    using pugi::xml_node;
    using pugi::xml_document;
    using pugi::xml_parse_result;

    xml_document doc;
    xml_parse_result result = doc.load_string(document);

    if (!result)
        throw std::runtime_error("Camera definitions parse error");

    // FIX: Validate "Cameras" element exists
    xml_node cameras_node = doc.child("Cameras");
    if (!cameras_node)
        throw std::runtime_error("Missing 'Cameras' root element in camera definitions");

    for (xml_node camera : cameras_node.children("Camera"))
    {
        const auto* cam = addCamera(std::make_unique<Camera>(camera));

        if (cam == nullptr)
            continue;

        for (auto i = 0UL; i < cam->aliases.size(); i++)
            addCamera(std::make_unique<Camera>(cam, i));
    }
}
```

